35	export default async function ColdEmailDomains() {
36	  await requireArea("platform");
37	
38	  const [brands, domains, inboxMetrics] = await Promise.all([
39	    db.brand.findMany({ orderBy: { createdAt: "asc" }, select: { id: true, name: true } }),
40	    db.sendingDomain.findMany({
41	      orderBy: { addedAt: "asc" },
42	      include: { brand: { select: { name: true } }, inboxes: { orderBy: { createdAt: "asc" } }, _count: { select: { inboxes: true } } },
43	    }),
44	    // Mailbox-level lifetime rollup (from the MetricsDaily spine).
45	    db.metricsDaily.groupBy({
46	      by: ["scopeId"],
47	      where: { scope: "INBOX" },
48	      _sum: { sent: true, delivered: true, hardBounce: true, softBounce: true, replies: true, unsubscribes: true },
49	    }),
50	  ]);
51	
52	  const inboxStats = new Map(
53	    inboxMetrics.map((m) => [
54	      m.scopeId,
55	      {
56	        sent: m._sum.sent ?? 0,
57	        bounced: (m._sum.hardBounce ?? 0) + (m._sum.softBounce ?? 0),
58	        replied: m._sum.replies ?? 0,
59	        unsub: m._sum.unsubscribes ?? 0,
60	      },
61	    ]),
62	  );
63	
64	  const brandOptions = brands.map((b) => ({ id: b.id, label: b.name }));
65	  const domainOptions = domains.map((d) => ({ id: d.id, label: `${d.subdomain}.${d.domain} (${d.brand.name})` }));
66	
67	  return (
68	    <div className="space-y-6">
69	      <PageHeader
70	        title="Domains &amp; inboxes"
71	        sub="Multi-domain / multi-inbox rotation substrate. Reputation is isolated on dedicated lookalike domains — a burn never touches the primary brand or platform mail."
72	      />
73	
74	      <div className="card">
75	        <p className="section-label mb-4">Add a sending domain</p>
76	        <SendingDomainForm brands={brandOptions} />
77	      </div>
78	
79	      <div className="card">
80	        <p className="section-label mb-4">Add an inbox</p>
81	        <InboxForm domains={domainOptions} />
82	      </div>
83	
84	      {domains.length === 0 ? (
85	        <EmptyState title="No sending domains yet" sub="Register a dedicated cold-email domain (never your primary brand domain) to start building a rotation pool." />
86	      ) : (
87	        <div className="space-y-6">
88	          {domains.map((d) => {
89	            const checklist = domainReadiness(d);
90	            const ready = checklist.every((c) => c.ok);
91	            return (
92	              <div key={d.id} className="card space-y-4">
93	                <div className="flex flex-wrap items-start justify-between gap-3">
94	                  <div>
95	                    <div className="flex items-center gap-2">
96	                      <span className="font-medium text-white">
97	                        {d.subdomain}.{d.domain}
98	                      </span>
99	                      <Badge tone="slate">{d.brand.name}</Badge>
100	                      <StatusDot status={d.status} />
101	                      {d.isPrimary && <Badge tone="brand">primary</Badge>}
102	                      {ready ? <Badge tone="green">inbox-ready</Badge> : <Badge tone="amber">not ready</Badge>}
103	                    </div>
104	                    <p className="mt-1 text-xs text-slate-500">
105	                      {d._count.inboxes} inbox(es) · tracking {d.trackingDomain || "—"} · DMARC {d.dmarcPolicy.toLowerCase()}
106	                      {d.pausedReason ? ` · ${d.pausedReason}` : ""}
107	                    </p>
108	                  </div>
109	                  <DomainStatusButtons id={d.id} status={d.status} />
110	                </div>
111	
112	                {/* 2026 bulk-sender readiness */}
113	                <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
114	                  <p className="section-label mb-3">Readiness (2026 bulk-sender rules)</p>
115	                  <ul className="grid gap-2 sm:grid-cols-2">
116	                    {checklist.map((c) => (
117	                      <li key={c.label} className="flex items-start gap-2 text-sm">
118	                        <span className={c.ok ? "text-emerald-400" : "text-amber-400"}>{c.ok ? "✓" : "○"}</span>
119	                        <span>
120	                          <span className={c.ok ? "text-slate-200" : "text-amber-200"}>{c.label}</span>
121	                          <span className="block text-xs text-slate-500">{c.hint}</span>
122	                        </span>
123	                      </li>
124	                    ))}
125	                  </ul>
126	                  <p className="mt-3 text-xs text-slate-500">
127	                    Non-compliant senders see 22–34% inbox placement vs ~89% for compliant senders.{" "}
128	                    <a className="text-brand-300 hover:underline" href="https://redsift.com/guides/bulk-email-sender-requirements" target="_blank" rel="noreferrer">
129	                      Google/Yahoo + Microsoft guidance
130	                    </a>
131	                    .
132	                  </p>
133	                  {/* LIVE DNS verification — real lookups set the auth + tracking flags. */}
134	                  <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
135	                    <p className="section-label mb-2">Live DNS verification</p>
136	                    <SendingDomainDnsVerify
137	                      id={d.id}
138	                      fqdn={`${d.subdomain}.${d.domain}`}
139	                      hasTracking={!!d.trackingDomain}
140	                    />
141	                  </div>
142	
143	                  {/* Manual fallback (only if a live check isn't possible). */}
144	                  <div className="mt-3">
145	                    <DomainVerificationForm
146	                      id={d.id}
147	                      spfVerified={d.spfVerified}
148	                      dkimVerified={d.dkimVerified}
149	                      dmarcVerified={d.dmarcVerified}
150	                      trackingDomainVerified={d.trackingDomainVerified}
151	                      dmarcPolicy={d.dmarcPolicy}
152	                    />
153	                  </div>
154	                </div>
155	
156	                {/* Inboxes on this domain */}
157	                {d.inboxes.length > 0 && (
158	                  <div className="overflow-x-auto">
159	                    <table className="w-full text-sm">
160	                      <thead>
161	                        <tr className="text-left text-xs uppercase tracking-wide text-slate-500">
162	                          <th className="py-2 pr-3">Mailbox</th>
163	                          <th className="py-2 pr-3">Status</th>
164	                          <th className="py-2 pr-3">Warmup</th>
165	                          <th className="py-2 pr-3">Ramp / cap</th>
166	                          <th className="py-2 pr-3">Health</th>
167	                          <th className="py-2 pr-3 text-right">Sent</th>
168	                          <th className="py-2 pr-3 text-right">Bounced</th>
169	                          <th className="py-2 pr-3 text-right">Replied</th>
170	                          <th className="py-2 pr-3 text-right">Actions</th>
171	                        </tr>
172	                      </thead>
173	                      <tbody>
174	                        {d.inboxes.map((ib) => {
175	                          const day = warmupDayIndex(ib.warmupStartedAt, new Date());
176	                          const w = warmupStatus(day, { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays });
177	                          return (
178	                            <tr key={ib.id} className="border-t border-white/[0.05]">
179	                              <td className="py-2 pr-3 font-medium text-white">{ib.email}</td>
180	                              <td className="py-2 pr-3">
181	                                <StatusDot status={ib.status} />
182	                              </td>
183	                              <td className="py-2 pr-3 text-slate-400">{w.complete ? "warmed" : `day ${w.day + 1}/${w.rampDays}`}</td>
184	                              <td className="py-2 pr-3 text-slate-400">
185	                                {ib.currentRampCap}/{ib.dailyCap}
186	                              </td>
187	                              <td className="py-2 pr-3 text-slate-400">{ib.healthScore}</td>
188	                              <td className="py-2 pr-3 text-right text-slate-300">{inboxStats.get(ib.id)?.sent ?? 0}</td>
189	                              <td className="py-2 pr-3 text-right text-red-300">{inboxStats.get(ib.id)?.bounced ?? 0}</td>
190	                              <td className="py-2 pr-3 text-right text-emerald-300">{inboxStats.get(ib.id)?.replied ?? 0}</td>
191	                              <td className="py-2 pr-3">
192	                                <InboxControls id={ib.id} status={ib.status} />
193	                              </td>
194	                            </tr>
195	                          );
196	                        })}
197	                      </tbody>
198	                    </table>
199	                  </div>
200	                )}
201	              </div>
202	            );
203	          })}
204	        </div>
205	      )}
206	    </div>
207	  );
208	}
