1	import { db } from "@/lib/db";
2	import { requireArea } from "@/lib/rbac";
3	import { PageHeader, Badge, StatusDot, EmptyState } from "@/components/ui/primitives";
4	import { warmupStatus, warmupRampCurve, WARMUP_MODES, type WarmupModeKey } from "@/lib/coldemail/warmup";
5	import { warmupDayIndex } from "@/lib/coldemail/compliance";
6	import { InboxControls } from "@/components/admin/coldemail/Phase3Controls";
7	
8	export const dynamic = "force-dynamic";
9	
10	/** Compact planned-ramp bar chart; highlights the current warmup day. */
11	function RampChart({ startCap, targetCap, rampDays, currentDay }: { startCap: number; targetCap: number; rampDays: number; currentDay: number }) {
12	  const curve = warmupRampCurve({ startCap, targetCap, rampDays });
13	  const max = Math.max(1, targetCap);
14	  return (
15	    <div className="flex h-16 items-end gap-[2px]">
16	      {curve.map((p) => {
17	        const h = Math.max(6, Math.round((p.planned / max) * 100));
18	        const isNow = p.day === Math.min(currentDay, rampDays);
19	        return (
20	          <div
21	            key={p.day}
22	            title={`Day ${p.day + 1}: ${p.planned}/day`}
23	            style={{ height: `${h}%` }}
24	            className={`w-full rounded-sm ${isNow ? "bg-brand-400" : p.day < currentDay ? "bg-brand-500/70" : "bg-white/10"}`}
25	          />
26	        );
27	      })}
28	    </div>
29	  );
30	}
31	
32	export default async function ColdEmailWarming() {
33	  await requireArea("platform");
34	
35	  const inboxes = await db.inbox.findMany({
36	    orderBy: [{ status: "asc" }, { createdAt: "asc" }],
37	    include: { sendingDomain: { select: { domain: true, subdomain: true, brand: { select: { name: true } } } } },
38	  });
39	
40	  return (
41	    <div className="space-y-6">
42	      <PageHeader
43	        title="Warming"
44	        sub="Per-inbox warmup ramps. New inboxes send a handful/day and climb to their ceiling over 2–4 weeks, building trusted sending history before any campaign volume."
45	      />
46	
47	      <div className="rounded-xl border border-amber-500/25 bg-amber-500/[0.06] p-4 text-sm text-amber-200/90">
48	        <p className="font-medium text-amber-200">Favor real engagement over synthetic warmup.</p>
49	        <p className="mt-1 text-amber-200/80">
50	          Genuine replies + spam-rescue on a small vetted seed (real-seed / hybrid) build reputation safely. Synthetic auto-open pools are
51	          increasingly detected by Gmail/Yahoo in 2026 and can <em>damage</em> deliverability — and a real shared warmup network cannot be
52	          self-hosted (SaaS-pool territory, out of scope).
53	        </p>
54	      </div>
55	
56	      {inboxes.length === 0 ? (
57	        <EmptyState title="No inboxes to warm" sub="Add inboxes under Domains & inboxes, then start their warmup here." />
58	      ) : (
59	        <div className="grid gap-5 lg:grid-cols-2">
60	          {inboxes.map((ib) => {
61	            const day = warmupDayIndex(ib.warmupStartedAt, new Date());
