export async function importBusinessesCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");

  const csv = String(formData.get("csv") ?? "");
  const recordConsentAll = formData.get("recordConsent") === "on" || formData.get("recordConsent") === "true";
  if (!csv.trim()) return { error: "Paste some CSV rows first." };

  const { headers, rows } = parseCsv(csv);
  if (headers.length === 0 || rows.length === 0) {
    return { error: "Could not find a header row and at least one data row." };
  }
  const cols = headers.map((h) => HEADER_ALIASES[h] ?? "");
  if (!cols.includes("name")) {
    return { error: "CSV needs at least a 'name' (business name) column." };
  }

  let created = 0;
  let contactsCreated = 0;
  let skipped = 0;

  for (const r of rows) {
    const rec: Record<string, string> = {};
    cols.forEach((field, i) => {
      if (field) rec[field] = (r[i] ?? "").trim();
    });
    const name = (rec.name ?? "").trim();
    if (!name) {
      skipped++;
      continue;
    }
    try {
      const business = await db.business.create({
        data: {
          name: name.slice(0, 160),
          category: (rec.category ?? "").slice(0, 120),
          businessType: (rec.businessType ?? "").slice(0, 120),
          website: (rec.website ?? "").slice(0, 200),
          phone: (rec.phone ?? "").slice(0, 60),
          addressLine: (rec.addressLine ?? "").slice(0, 200),
          city: (rec.city ?? "").slice(0, 120),
          region: (rec.region ?? "").slice(0, 120),
          country: (rec.country ?? "").slice(0, 120),
          companySize: (rec.companySize ?? "").slice(0, 60),
          source: "csv",
        },
      });
      created++;

      const email = normalizeEmail(rec.email);
      if (email && emailSchema.safeParse(email).success) {
        const clash = await db.contact.findUnique({ where: { email }, select: { id: true } });
        if (!clash) {
          const contact = await db.contact.create({
            data: {
              businessId: business.id,
              fullName: (rec.fullName ?? "").slice(0, 160),
              title: (rec.title ?? "").slice(0, 120),
              email,
            },
          });

